// This function reads the value of `x` from the `PAtomicU32`
// that's part of this `CounterSharedState`. It requires, as
// input, two `OneShotResource`s, one showing that thread 0's
// one-shot is complete and the other showing that thread 1's
// one-shot is complete. Because of these, it can ensure that the
// value it reads is 2.
pub fn read_x(
    self: &Arc<Self>,
    Tracked(oneshot0_complete): Tracked<OneShotResource>,
    Tracked(oneshot1_complete): Tracked<OneShotResource>,
) -> (x: u32)
    requires
        self.wf(),
        oneshot0_complete.id() == self.get_oneshot_id(0),
        oneshot1_complete.id() == self.get_oneshot_id(1),
        oneshot0_complete@ is Complete,
        oneshot1_complete@ is Complete,
    ensures
        x == 2,
{
    let x_value: u32;
    open_atomic_invariant!(self.inv.borrow() => inner => {
        proof {
            // We need to prove that both one-shots in the invariant are complete.
            // We can do this by using lemma_is_complete_if_other_is.

            // First, show that oneshot0 in the invariant is complete
            let tracked mut inv_oneshot0 = inner.oneshot0_inv_half;
            oneshot0_complete.lemma_is_complete_if_other_is(&mut inv_oneshot0);
            assert(inv_oneshot0@ is Complete);

            // Then, show that oneshot1 in the invariant is complete
            let tracked mut inv_oneshot1 = inner.oneshot1_inv_half;
            oneshot1_complete.lemma_is_complete_if_other_is(&mut inv_oneshot1);
            assert(inv_oneshot1@ is Complete);

            // Now we can assert that both are complete
            assert(inner.oneshot0_inv_half@ is Complete);
            assert(inner.oneshot1_inv_half@ is Complete);

            // By the invariant definition, x_perm.value should be 2
            assert(inner.x_perm@.value == 2);
        }
        x_value = self.x.load(Tracked(&inner.x_perm));
        assert(x_value == 2); // This is the key assertion we needed to prove.
    });
    x_value
}

