pub proof fn lemma_is_complete_if_other_is(tracked &mut self, tracked other: &Self)
    requires
        other.id() == old(self).id(),
        other@ is Complete,
        old(self)@ is HalfRightToComplete,
    ensures
        final(self).id() == old(self).id(),
        final(self)@ == old(self)@,
        final(self)@ is Complete,
{
    // Since other is complete and they share the same location,
    // and self has HalfRightToComplete, we can combine them to make Complete
    let tracked self_r = self.r.extract();
    let tracked other_r = other.r.extract();

    // Combine the resources
    let tracked combined = self_r.join(other_r);

    // Update to complete state
    let tracked updated = combined.update(OneShotResourceValue::Complete);

    // Split back - one stays with self, one is returned to other
    let tracked (mut complete_self, complete_other) = updated.split(
        OneShotResourceValue::Complete,
        OneShotResourceValue::Complete
    );

    // Put the complete resource back in self
    tracked_swap(&mut self.r, &mut complete_self);

    assert(final(self)@ is Complete);
}

